const downloadInterviewCalendar=(interview:Interview,title:string)=>{
 const start=new Date(interview.scheduledAt);const end=new Date(start.getTime()+interview.durationMinutes*60000);
 const fmt=(d:Date)=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
 const location=interview.mode==='presencial'?(interview.location||''):interview.meetingUrl||'';
 const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//TalentOS Industrial//PT-BR','BEGIN:VEVENT','UID:'+interview.id+'@talentos-industrial','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(start),'DTEND:'+fmt(end),'SUMMARY:'+title.replace(/[\r\n]/g,' '),'LOCATION:'+location.replace(/[\r\n]/g,' '),'END:VEVENT','END:VCALENDAR'].join('\r\n');
 const blob=new Blob([ics],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='entrevista-'+interview.id+'.ics';a.click();URL.revokeObjectURL(url);
};

