const funnelAnalises=useMemo(()=>{
 const stages:Status[]=['novo','triagem','entrevista','aprovado','contratado'];
 const counts=stages.map(status=>({status,count:db.applications.filter(a=>a.status===status).length}));
 const byTransition=new Map<string,number[]>();
 const byApp=new Map<string,AppEvent[]>();
 db.events.forEach(e=>{
   const list=byApp.get(e.applicationId)??[];
   list.push(e);byApp.set(e.applicationId,list);
 });
 byApp.forEach(events=>{
   const ordered=[...events].sort((a,b)=>a.at.localeCompare(b.at));
   for(let i=1;i<ordered.length;i++){
     const current=ordered[i];
     if(!current.fromStatus)continue;
     const previous=ordered[i-1];
     const hours=Math.max(0,(new Date(current.at).getTime()-new Date(previous.at).getTime())/3600000);
     const key=current.fromStatus+'→'+current.toStatus;
     const values=byTransition.get(key)??[];
     values.push(hours);byTransition.set(key,values);
   }
 });
 const transitions=Array.from(byTransition.entries()).map(([label,values])=>({label,avgHours:values.reduce((a,b)=>a+b,0)/values.length,count:values.length})).sort((a,b)=>a.avgHours-b.avgHours);
 const total=db.applications.length;
 const atInterview=db.applications.filter(a=>['entrevista','aprovado','contratado'].includes(a.status)).length;
 const approvedOrHired=db.applications.filter(a=>['aprovado','contratado'].includes(a.status)).length;
 const hired=db.applications.filter(a=>a.status==='contratado').length;
 return {counts,transitions,total,interviewRate:total?atInterview/total:0,approvalRate:total?approvedOrHired/total:0,hireRate:total?hired/total:0};
},[db.applications,db.events]);
