const createJobAlertHandler=async()=>{
 if(!session||role!=='candidato')return;
 try{
  if(!alertCriteria.length)throw new Error('Escolha pelo menos um critério para o alerta.');
  const selected=(field:string)=>alertCriteria.includes(field);
  const required:[string,string,string][]=[
   ['cargo',alertValues.cargo,'Escolha o cargo do alerta.'],['skill',alertValues.skill,'Escolha a competência do alerta.'],
   ['city',alertValues.city,'Escolha a cidade do alerta.'],['company',alertValues.company,'Escolha a empresa do alerta.'],
   ['minSalary',alertValues.minSalary,'Informe o salário mínimo do alerta.'],['shift',alertValues.shift,'Escolha o turno do alerta.'],
   ['workModel',alertValues.workModel,'Escolha a modalidade do alerta.']
  ];
  for(const [field,value,message] of required){if(selected(field)&&!value.trim())throw new Error(message)}
  const city=selected('city')?(dataMode==='remote'?await requireCanonicalCity(alertValues.city):alertValues.city):'';
  const minimumSalary=selected('minSalary')?parseBrazilianMoney(alertValues.minSalary):0;
  if(selected('minSalary')&&minimumSalary<=0)throw new Error('Informe um salário mínimo válido.');
  const labels=[
   selected('cargo')&&alertValues.cargo,selected('skill')&&alertValues.skill,selected('city')&&city,
   selected('company')&&alertValues.company,selected('shift')&&alertValues.shift
  ].filter(Boolean);
  const name=jobAlertName.trim()||labels.join(' · ')||'Alerta de vagas';
  const input={
   name,
   cargo:selected('cargo')?alertValues.cargo:undefined,
   skill:selected('skill')?alertValues.skill:undefined,
   city:selected('city')?city:undefined,
   company:selected('company')?alertValues.company:undefined,
   minSalary:selected('minSalary')?minimumSalary:undefined,
   shift:selected('shift')?alertValues.shift:undefined,
   workModel:selected('workModel')?alertValues.workModel:undefined
  };
  if(dataMode==='remote'){await createRemoteJobAlert(session.user.id,input);await reloadRemote()}
  else{
   const row={id:'al'+Date.now(),candidateId:session.user.id,name,cargo:input.cargo??null,skill:input.skill??null,city:input.city??null,company:input.company??null,minSalary:input.minSalary??null,maxSalary:null,shift:input.shift??null,workModel:input.workModel??null,active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
   persist({...db,jobAlerts:[...db.jobAlerts,row]},'Alerta de vagas criado');
  }
  setModal(null);setToast('Alerta de vagas criado');
 }catch(err){console.error(err);setToast(localizeDisplayedText(err instanceof Error?err.message:'Não foi possível criar o alerta'))}
};
