const interviewCandidateAvailability=useMemo(()=>{
  const app=interviewApplicationId?db.applications.find(a=>a.id===interviewApplicationId):null;
  const candidateId=app?.candidateId;
  if(!candidateId)return [];
  const weekly=db.candidateAvailability.filter(x=>x.candidateId===candidateId&&x.active);
  const out:Array<{label:string;value:string}>=[];const now=new Date();
  for(let dayOffset=1;dayOffset<=14&&out.length<6;dayOffset++){
    const d=new Date(now);d.setDate(now.getDate()+dayOffset);
    const weekday=d.getDay();
    for(const slot of weekly.filter(x=>x.weekday===weekday).slice(0,2)){
      const candidateDate=new Date(d.getFullYear(),d.getMonth(),d.getDate(),Number(slot.startTime.slice(0,2)),Number(slot.startTime.slice(3,5)),0,0);
      if(candidateDate>now)out.push({label:candidateDate.toLocaleString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}),value:new Date(candidateDate.getTime()-candidateDate.getTimezoneOffset()*60000).toISOString().slice(0,16)});
      if(out.length>=6)break;
    }
  }
  return out;
},[db.applications,db.candidateAvailability,interviewApplicationId]);
