const loadBrazilCities=async()=>{if(brazilCitiesRef.current)return brazilCitiesRef.current;if(brazilCitiesLoadRef.current)return brazilCitiesLoadRef.current;if(!supabase)throw new Error('Supabase não configurado');const loadPromise=getRemoteBrazilCities().then(rows=>{const mapped=rows.map(x=>({name:x.name,uf:x.uf}));brazilCitiesRef.current=mapped;return mapped}).finally(()=>{brazilCitiesLoadRef.current=null});brazilCitiesLoadRef.current=loadPromise;return loadPromise};
const updateCitySuggestions=async(value:string)=>{const prefix=value.trim();const req=++citySearchRequestRef.current;if(!prefix){setCityOptions([]);return}try{const rows=await loadBrazilCities();if(req!==citySearchRequestRef.current)return;const q=normalizeCityText(prefix);const suggestions=rows.filter(city=>normalizeCityText(city.name).startsWith(q)).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')||a.uf.localeCompare(b.uf,'pt-BR')).map(city=>cityLabel(city.name,city.uf));setCityOptions(suggestions)}catch(err){console.error('city autocomplete',err);setCityOptions([]);setToast('Não foi possível carregar a lista oficial de municípios')}};
const requireCanonicalCity=async(value:string)=>{const rows=await loadBrazilCities();const canonical=canonicalizeCity(value,rows);if(!canonical)throw new Error('Selecione uma cidade da lista oficial de municípios.');return canonical};
useEffect(()=>{if(!supabase||!session)return;let mounted=true;loadBrazilCities().then(rows=>{if(mounted)setOfficialCityCatalog(rows.map(city=>cityLabel(city.name,city.uf))) }).catch(err=>console.error('city catalog',err));return()=>{mounted=false}},[session?.user?.id]);
useEffect(()=>{if(!session||!role)return;const allowed:Tab[]=role==='candidato'?['jobs','passport','applications','skills','settings']:role==='empresa'?['dashboard','jobs','talents','passport','pipeline','validation','skills','intelligence','team','settings']:['dashboard','jobs','talents','companies','skills','intelligence','passport','applications','pipeline','validation','settings'];if(!allowed.includes(tab))setTab('jobs')},[session,role,tab]);
const createJob=async()=>{try{
 const skills=f.skills.split(',').map(x=>x.trim()).filter(Boolean);
 if(!roleCatalog.includes(f.title)&&!db.jobs.some(j=>j.title===f.title))throw new Error('Selecione um cargo da lista.');
 if(!skills.length||skills.some(x=>!skillCatalog.includes(x)))throw new Error('Selecione as competências da lista.');
 if(!SHIFT_OPTIONS.includes(f.shift as typeof SHIFT_OPTIONS[number]))throw new Error('Selecione um turno válido.');
 const city=dataMode==='remote'?await requireCanonicalCity(f.city):f.city.trim();
 const screeningQuestions=f.screeningQuestions.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8);
 const interviewQuestions=f.interviewQuestions.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,10);
 const benefits=f.benefits.split(',').map(x=>x.trim()).filter(Boolean);
 const minimumSalary=parseBrazilianMoney(f.min);
 const payload={title:f.title,description:f.description,city,min:minimumSalary,max:minimumSalary,skills,shift:f.shift,screeningQuestions,employmentType:f.employmentType,workModel:f.workModel,benefits,travelRequired:f.travelRequired,interviewQuestions};
 if(dataMode==='remote'&&session){
  if(!['empresa','admin'].includes(role??''))throw new Error('Somente contas empresariais ou administrativas podem salvar vagas');
  if(editingJobId){
   await updateRemoteJobDetails({jobId:editingJobId,...payload});
   await reloadRemote();
   await generateRemoteMatches(editingJobId);
   await reloadRemote();
   setJobId(editingJobId);
   setToast('Vaga atualizada · compatibilidade recalculada');
  }else{
   if(!f.companyId)throw new Error('Cadastre a empresa antes de criar a vaga');
   const j=await createRemoteJob(session.user.id,{...payload,companyId:f.companyId});
   await reloadRemote();await generateRemoteMatches(j.id);await reloadRemote();setJobId(j.id);
   setToast('Vaga criada · correspondência atualizada');
  }
 }else if(editingJobId){
  const current=db.jobs.find(j=>j.id===editingJobId);if(!current)throw new Error('Vaga não encontrada');
  persist({...db,jobs:db.jobs.map(j=>j.id===editingJobId?{...j,...payload,description:payload.description||null}:j)},'Vaga atualizada');
 }else{
  const id='j'+Date.now();
  persist({...db,jobs:[...db.jobs,{id,...payload,description:payload.description||null,companyId:f.companyId,status:'aberta'}]},'Vaga criada');
 }
 setEditingJobId(null);setModal(null);setTab('jobs');
}catch(err){console.error(err);setToast(localizeDisplayedText(err instanceof Error?err.message:'Não foi possível salvar a vaga'))}};
