const move=async(id:string,status:Status,rejectionReasonCode?:string|null,rejectionReasonText?:string|null)=>{
 const current=db.applications.find(a=>a.id===id);
 if(!current||current.status===status)return;
 if(status==='rejeitado'&&!rejectionReasonCode){
  setRejectionApplicationId(id);
  setRejectionReason('habilidades');
  setRejectionNote('');
  setModal('rejection');
  return;
 }
 try{
  if(dataMode==='remote'){
   await updateRemoteApplication(id,status,rejectionReasonCode??null,rejectionReasonText??null);
   await reloadRemote();
  }else{
   const note=status==='rejeitado'
    ?'Motivo da rejeição: '+rejectionReasonLabel(rejectionReasonCode)+(rejectionReasonText?.trim()?' · '+rejectionReasonText.trim():'')
    :undefined;
   const event:AppEvent={id:'ev'+Date.now(),applicationId:id,fromStatus:current.status,toStatus:status,at:new Date().toISOString(),note};
   persist({
    ...db,
    applications:db.applications.map(a=>a.id===id?{
      ...a,
      status,
      rejectionReasonCode:status==='rejeitado'?rejectionReasonCode??null:null,
      rejectionReasonNote:status==='rejeitado'?rejectionReasonText?.trim()||null:null
    }:a),
    events:[...db.events,event]
   },'Pipeline atualizado');
  }
 }catch(err){console.error(err);setToast('Não foi possível atualizar')}
};
