const resendSignupConfirmation=async()=>{
 if(!supabase||!authEmail.trim()||authBusy||!signupConfirmationRequested)return;
 try{
  setAuthBusy(true);setAuthMsg('');
  const {error}=await supabase.auth.resend({type:'signup',email:authEmail.trim(),options:{emailRedirectTo:window.location.origin}});
  if(error)throw error;
  setAuthMsg('Nova confirmação solicitada. Se o provedor de e-mail estiver configurado corretamente, a mensagem chegará neste endereço.');
 }catch(err){console.error(err);setAuthMsg(localizeDisplayedText(err instanceof Error?err.message:'Não foi possível reenviar a confirmação'))}
 finally{setAuthBusy(false)}
}; const submitAuth=async()=>{if(!supabase||authBusy)return;try{setAuthBusy(true);setAuthMsg('');if(authMode==='login'){const result=await supabase.auth.signInWithPassword({email:authEmail.trim(),password:authPassword});if(result.error)throw result.error;const signedUser=result.data.user;if(!signedUser)throw new Error('Não foi possível identificar a conta.');const profile=await getRemoteProfile(signedUser.id);const pendingTeamInvite=new URLSearchParams(window.location.search).has('teamInvite');const pendingCompanySetup=profile?.role==='candidato'&&signedUser.user_metadata?.requested_account_type==='empresa';const allowed=pendingTeamInvite?true:authAudience==='empresa'?profile?.role==='empresa'||profile?.role==='admin'||pendingCompanySetup:profile?.role==='candidato'&&!pendingCompanySetup;if(!allowed){await supabase.auth.signOut();setAuthPassword('');if(authAudience==='empresa')throw new Error('Esta conta não possui acesso empresarial. Use “Entrar como candidato” ou peça ao TalentOS para liberar o acesso da sua empresa.');throw new Error('Esta conta é empresarial. Use “Entrar como empresa”.');}setAuthModal(false)}else if(authMode==='signup'){if(authPassword.length<12||!/[a-z]/.test(authPassword)||!/[A-Z]/.test(authPassword)||!/[0-9]/.test(authPassword)||!/[^A-Za-z0-9]/.test(authPassword))throw new Error('Use uma senha com pelo menos 12 caracteres, incluindo maiúscula, minúscula, número e símbolo.');if(authPassword!==authPasswordConfirm)throw new Error('As senhas não coincidem.');setSignupConfirmationRequested(false);const result=await supabase.auth.signUp({email:authEmail.trim(),password:authPassword,options:{emailRedirectTo:window.location.origin,data:{requested_account_type:authAudience}}});if(result.error)throw result.error;if(!result.data.user?.id)throw new Error('A conta não foi registrada. Tente novamente.');const identities=result.data.user.identities;if(Array.isArray(identities)&&identities.length===0){setAuthPassword('');setAuthPasswordConfirm('');setAuthMode('login');setAuthMsg('Este e-mail já possui uma conta no TalentOS. Entre com sua senha. Se não lembrar, use “Alterar ou recuperar minha senha”.');}else{setAuthPassword('');setAuthPasswordConfirm('');if(result.data.session){setSignupConfirmationRequested(false);setAuthModal(false);setAuthMsg(authAudience==='empresa'?'Conta criada. Complete os dados da empresa para liberar o acesso empresarial.':'Conta criada e acesso liberado.')}else{setSignupConfirmationRequested(true);setAuthMsg('Conta criada e confirmação solicitada. Verifique sua caixa de entrada e Spam. Se não chegar, use “Reenviar confirmação”.')}}}else if(authMode==='recovery'){if(!authEmail.trim())throw new Error('Informe seu e-mail.');const {error}=await supabase.auth.resetPasswordForEmail(authEmail.trim(),{redirectTo:window.location.origin});if(error)throw error;setAuthMsg('Enviamos as instruções de recuperação para seu e-mail.')}else if(authMode==='reset'||authMode==='change'){if(authPassword.length<12||!/[a-z]/.test(authPassword)||!/[A-Z]/.test(authPassword)||!/[0-9]/.test(authPassword)||!/[^A-Za-z0-9]/.test(authPassword))throw new Error('Use uma senha com pelo menos 12 caracteres, incluindo maiúscula, minúscula, número e símbolo.');if(authPassword!==authPasswordConfirm)throw new Error('As senhas não coincidem.');const {error}=await supabase.auth.updateUser({password:authPassword});if(error)throw error;setAuthPassword('');setAuthPasswordConfirm('');setAuthMsg('Senha atualizada com sucesso.');if(authMode==='reset')setAuthMode('login');}}catch(err){console.error(err);setAuthMsg(localizeDisplayedText(err instanceof Error?err.message:'Não foi possível concluir a operação'))}finally{setAuthBusy(false)}};
const heading={dashboard:role==='empresa'?'Início':'Visão geral',jobs:role==='empresa'?'Minhas vagas':'Vagas',talents:role==='empresa'?'Candidatos':'Profissionais',companies:'Empresas',skills:role==='candidato'?'Competências e desenvolvimento':role==='empresa'?'Competências':'Mapa de competências',intelligence:'Análises',passport:role==='candidato'?'Meu currículo':'Perfil de competências',applications:'Minhas candidaturas',pipeline:'Processo seletivo',validation:role==='empresa'?'Comprovações':'Validar competências',settings:role==='candidato'?'Configurações da conta':'Configurações',team:'Equipe da empresa'}[tab];
